//! RFC 3161 tokens from an independent TSA (OpenSSL, regenerated by
//! scripts/generate-cms-timestamp-fixtures.sh) checked by the published CMS
//! timestamp processor through xml-sec's selected provider and policy.
#![cfg(feature = "cms")]

use std::sync::Arc;

use structured_asn1::memory::{Memory, MemoryAccount};
use structured_asn1::{Encoding, Parser, digest::Resolution};
use structured_cms::content_source::ContentError;
use structured_cms::digest::DigestError;
use structured_cms::ess::BindingError;
use structured_cms::prepare::PrepareError;
use structured_cms::provider::{SignatureAnswer, SignatureMode, SignatureProvider};
use structured_cms::timestamp::{
    CheckContext, CheckError, ImprintAgreement, InfoCheckError, InfoError, SignatureError, Token,
    TokenSignature,
};
use structured_pkix::Certificate;
use structured_pkix::path::WorkingKey;
use structured_pkix::temporal::{Instant, LeapTable};
use xml_sec::policy::{CertificateSignatureAlgorithms, VerificationPolicy};
#[cfg(not(feature = "xmlenc"))]
use xml_sec::provider::{
    CryptoProvider, DigestState, KdfParameters, ProviderCapability, ProviderError,
};
use xml_sec::provider::{RustCryptoProvider, X509SignatureAlgorithm};
use xml_sec::xmldsig::DigestAlgorithm;
use xml_sec::xmldsig::cms::{CmsProvider, CmsProviderError};
#[cfg(not(feature = "xmlenc"))]
use xml_sec::xmldsig::{DsigError, SignatureAlgorithm, SigningKey, SigningKeyError, VerifyingKey};

const AUTHORITIES: [&str; 4] = ["rsa", "rsa-pss", "ecdsa-p256", "ed25519"];

fn fixture(name: &str) -> Vec<u8> {
    let path = format!(
        "{}/tests/fixtures/cms/timestamp/{name}",
        env!("CARGO_MANIFEST_DIR")
    );
    std::fs::read(&path).unwrap_or_else(|error| panic!("{path}: {error}"))
}

/// The facts of one completed check that the assertions below inspect.
#[derive(Debug, PartialEq, Eq)]
struct Outcome {
    signature: Option<SignatureAnswer>,
    imprint: ImprintAgreement,
    evidence: bool,
}

/// Why a check did not complete.
enum Refusal {
    /// The xml-sec provider refused, with its rendered cause.
    Provider(String),
    /// Token reading or common processing refused.
    Other(String),
}

impl Refusal {
    fn is_policy(&self) -> bool {
        matches!(self, Self::Provider(cause) if cause.starts_with("Policy("))
    }
}

impl core::fmt::Debug for Refusal {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self {
            Self::Provider(cause) => write!(f, "provider refusal: {cause}"),
            Self::Other(cause) => write!(f, "processing refusal: {cause}"),
        }
    }
}

/// The provider failure inside a refused check, if the refusal was one: from
/// signer preparation, signature state admission or the ESS certificate hash.
fn provider_failure<SE, RE>(
    error: &CheckError<SE, CmsProviderError, RE>,
) -> Option<&CmsProviderError> {
    let CheckError::Information(ContentError::Callback {
        source: InfoError::Callback(information),
        ..
    }) = error
    else {
        return None;
    };
    match information {
        InfoCheckError::Signature(
            SignatureError::Preparation(PrepareError::Callback { source, .. })
            | SignatureError::Admission(structured_cms::verify::CheckError::Callback(source)),
        )
        | InfoCheckError::Ess(
            BindingError::Callback { source, .. }
            | BindingError::Digest {
                source: DigestError::Callback(source),
                ..
            },
        ) => Some(source),
        _ => None,
    }
}

fn other(error: impl core::fmt::Display) -> Refusal {
    Refusal::Other(error.to_string())
}

/// Check `token` of authority `name` over `covered` with `policy`, on an
/// account limited to `limits` (storage, work). The account must be empty
/// once the check and every value it produced are dropped.
fn check(
    name: &str,
    token: &[u8],
    covered: &[u8],
    policy: &VerificationPolicy,
    limits: (usize, usize),
) -> Result<Outcome, Refusal> {
    let memory = Memory::new(Arc::new(MemoryAccount::new(limits.0, limits.1)));
    let certificate_bytes = fixture(&format!("{name}.der"));
    let result = (|| {
        let parser = Parser::ber(memory.clone());
        let cert_parser = Parser::der(memory.clone());
        let token = Token::read(&parser, token, 0).map_err(other)?;
        let parent = parser.read(&[], 0).map_err(other)?;
        let certificate = Certificate::read(&cert_parser, &certificate_bytes, 0).map_err(other)?;
        let certificate_parent = cert_parser.read(&[], 0).map_err(other)?;
        let utc = LeapTable::new(0, 2_000_000_000, &[]).expect("UTC facts");
        let provider = RustCryptoProvider;
        let cms = CmsProvider::new(&provider, policy);
        let context = CheckContext {
            certificate: &certificate,
            certificate_parent: &certificate_parent,
            key: WorkingKey::standing(certificate.tbs().public_key()),
            requested: None,
            utc: &utc,
            reference: Some(Instant::new(1_800_000_000, 0).expect("instant")),
            window: None,
        };
        match token.check(&cms, &parent, &context, &mut [covered], |_, _| {
            Ok::<_, ()>(false)
        }) {
            Ok(checked) => Ok(Outcome {
                signature: match &checked.signature {
                    TokenSignature::Checked(checked) => checked.signature(),
                    TokenSignature::Unsupported(_) | TokenSignature::Malformed(_) => None,
                },
                imprint: checked.imprint,
                evidence: checked.evidence().is_some(),
            }),
            Err(error) => Err(match provider_failure(&error) {
                Some(failure) => Refusal::Provider(format!("{failure:?}")),
                None => Refusal::Other(format!("{error:?}")),
            }),
        }
    })();
    assert_eq!(memory.used(), 0, "{name}: retained storage after the check");
    result
}

fn generous() -> (usize, usize) {
    (1 << 20, 1 << 24)
}

fn permissive() -> VerificationPolicy {
    let mut policy = VerificationPolicy::default();
    policy.key_trust.certificate_signature_algorithms =
        Some(CertificateSignatureAlgorithms::AllSupported);
    policy
}

#[test]
fn every_independent_authority_token_verifies_through_the_selected_provider() {
    // RSA PKCS #1 v1.5 (rsaEncryption), RSA-PSS, ECDSA P-256 and pure Ed25519
    // tokens from OpenSSL: each signature is valid, the imprint matches the
    // payload and the common checker retains timestamp evidence.
    let payload = fixture("payload.txt");
    for name in AUTHORITIES {
        let outcome = check(
            name,
            &fixture(&format!("{name}.tst")),
            &payload,
            &permissive(),
            generous(),
        )
        .unwrap_or_else(|error| panic!("{name}: {error:?}"));
        assert_eq!(
            outcome,
            Outcome {
                signature: Some(SignatureAnswer::Valid),
                imprint: ImprintAgreement::Matches,
                evidence: true,
            },
            "{name}"
        );
    }
}

#[test]
fn other_content_is_an_imprint_disagreement_not_an_error() {
    // The signature stays valid; only the covered content differs, so no
    // evidence is retained and nothing is reported as a processing error.
    for name in AUTHORITIES {
        let outcome = check(
            name,
            &fixture(&format!("{name}.tst")),
            b"Another payload\n",
            &permissive(),
            generous(),
        )
        .unwrap_or_else(|error| panic!("{name}: {error:?}"));
        assert_eq!(outcome.signature, Some(SignatureAnswer::Valid), "{name}");
        assert_eq!(outcome.imprint, ImprintAgreement::Differs, "{name}");
        assert!(!outcome.evidence, "{name}");
    }
}

#[test]
fn a_tampered_signature_value_is_invalid_not_an_error() {
    // Each token ends with its SignerInfo signature; flipping the final octet
    // keeps every encoding readable, so the arithmetic must reject it.
    let payload = fixture("payload.txt");
    for name in AUTHORITIES {
        let mut token = fixture(&format!("{name}.tst"));
        let last = token.len() - 1;
        token[last] ^= 0x01;
        let outcome = check(name, &token, &payload, &permissive(), generous())
            .unwrap_or_else(|error| panic!("{name}: {error:?}"));
        assert_eq!(outcome.signature, Some(SignatureAnswer::Invalid), "{name}");
        assert!(!outcome.evidence, "{name}");
    }
}

#[test]
fn a_signature_algorithm_outside_the_policy_is_a_policy_violation() {
    // Only Ed25519 certificate signatures are permitted: every other token is
    // refused as a typed policy violation before any signed byte is read.
    let mut policy = VerificationPolicy::default();
    policy.key_trust.certificate_signature_algorithms =
        Some(CertificateSignatureAlgorithms::Allowlist(
            [X509SignatureAlgorithm::Ed25519].into_iter().collect(),
        ));
    let payload = fixture("payload.txt");
    for name in AUTHORITIES {
        let result = check(
            name,
            &fixture(&format!("{name}.tst")),
            &payload,
            &policy,
            generous(),
        );
        if name == "ed25519" {
            assert!(result.is_ok_and(|outcome| outcome.evidence), "{name}");
        } else {
            let refusal = result.expect_err(name);
            assert!(refusal.is_policy(), "{name}: {refusal:?}");
        }
    }
}

#[test]
fn a_digest_outside_the_policy_is_a_policy_violation() {
    // The Ed25519 token uses SHA-512 for its signer digest and ESS certificate
    // hash; without SHA-512 in the digest policy the first of them to start is
    // refused as a typed violation, never treated as a mismatch.
    let mut policy = permissive();
    policy.digest_algorithms = Some([DigestAlgorithm::Sha256].into_iter().collect());
    let refusal = check(
        "ed25519",
        &fixture("ed25519.tst"),
        &fixture("payload.txt"),
        &policy,
        generous(),
    )
    .expect_err("SHA-512 is not permitted");
    assert!(refusal.is_policy(), "{refusal:?}");
}

#[test]
fn exhausted_work_is_a_refusal_never_a_negative_answer() {
    // Below the work the complete check needs, the outcome is a refusal; it is
    // never reported as an invalid signature or a different imprint. `check`
    // asserts that every refused attempt released its storage, including the
    // buffered signedAttrs.
    let payload = fixture("payload.txt");
    let token = fixture("rsa.tst");
    let valid = Outcome {
        signature: Some(SignatureAnswer::Valid),
        imprint: ImprintAgreement::Matches,
        evidence: true,
    };
    let mut refused = 0;
    for work in (0..=16).map(|shift| 1usize << shift) {
        match check("rsa", &token, &payload, &permissive(), (1 << 20, work)) {
            Ok(outcome) => assert_eq!(outcome, valid, "work {work}"),
            Err(_) => refused += 1,
        }
    }
    assert!(refused > 0, "no work ceiling refused the check");
    assert!(check("rsa", &token, &payload, &permissive(), generous()).is_ok_and(|o| o == valid));
}

#[test]
fn exhausted_storage_is_a_refusal_never_a_negative_answer() {
    // As for work: below the storage the check needs the outcome is a refusal,
    // and `check` asserts that the refused attempt retained nothing.
    let payload = fixture("payload.txt");
    let token = fixture("rsa.tst");
    let mut refused = 0;
    for storage in (0..=20).map(|shift| 1usize << shift) {
        match check(
            "rsa",
            &token,
            &payload,
            &permissive(),
            (storage, generous().1),
        ) {
            Ok(outcome) => assert!(outcome.evidence, "storage {storage}"),
            Err(_) => refused += 1,
        }
    }
    assert!(refused > 0, "no storage ceiling refused the check");
}

#[test]
fn an_identifier_that_names_no_signature_algorithm_is_unsupported() {
    // id-ecPublicKey identifies a key, not a signature; it is neither a
    // refusal nor malformed.
    let memory = Memory::new(Arc::new(MemoryAccount::new(1 << 20, 1 << 24)));
    let parser = Parser::der(memory);
    let policy = permissive();
    let provider = RustCryptoProvider;
    let cms = CmsProvider::new(&provider, &policy);
    let parent = parser.read(&[], 0).expect("reader");
    let bytes = fixture("ecdsa-p256.der");
    let certificate = Certificate::read(&parser, &bytes, 0).expect("certificate");
    let key = certificate.tbs().public_key();
    assert!(matches!(
        cms.resolve_signature(
            key.algorithm(),
            &DigestAlgorithm::Sha256,
            WorkingKey::standing(key),
            Encoding::Der,
            &parent,
        ),
        Ok(Resolution::Unsupported)
    ));
}

/// The bundled provider without Ed25519 certificate signatures. Encryption
/// builds extend the provider contract; the `cms-xmloxide` profile runs this.
#[cfg(not(feature = "xmlenc"))]
struct WithoutEd25519;

#[cfg(not(feature = "xmlenc"))]
impl CryptoProvider for WithoutEd25519 {
    fn name(&self) -> &'static str {
        "without-ed25519"
    }
    fn supports(&self, capability: ProviderCapability<'_>) -> bool {
        !matches!(
            capability,
            ProviderCapability::VerifyCertificate(X509SignatureAlgorithm::Ed25519)
        ) && RustCryptoProvider.supports(capability)
    }
    fn sign(
        &self,
        key: &dyn SigningKey,
        algorithm: SignatureAlgorithm,
        input: &[u8],
    ) -> Result<Vec<u8>, SigningKeyError> {
        RustCryptoProvider.sign(key, algorithm, input)
    }
    fn verify(
        &self,
        key: &dyn VerifyingKey,
        algorithm: SignatureAlgorithm,
        input: &[u8],
        signature: &[u8],
    ) -> Result<bool, DsigError> {
        RustCryptoProvider.verify(key, algorithm, input, signature)
    }
    fn fill_random(&self, output: &mut [u8]) -> Result<(), ProviderError> {
        RustCryptoProvider.fill_random(output)
    }
    fn derive_key(
        &self,
        parameters: &KdfParameters<'_>,
        secret: &[u8],
    ) -> Result<Vec<u8>, ProviderError> {
        RustCryptoProvider.derive_key(parameters, secret)
    }
    fn begin_digest(
        &self,
        algorithm: DigestAlgorithm,
    ) -> Result<Box<dyn DigestState + '_>, ProviderError> {
        RustCryptoProvider.begin_digest(algorithm)
    }
}

#[cfg(not(feature = "xmlenc"))]
#[test]
fn an_algorithm_the_provider_lacks_is_unsupported_after_policy_permits_it() {
    // Policy permits Ed25519 here, so only the capability check can answer.
    let memory = Memory::new(Arc::new(MemoryAccount::new(1 << 20, 1 << 24)));
    let parser = Parser::der(memory);
    let policy = permissive();
    let cms = CmsProvider::new(&WithoutEd25519, &policy);
    let parent = parser.read(&[], 0).expect("reader");
    let bytes = fixture("ed25519.der");
    let certificate = Certificate::read(&parser, &bytes, 0).expect("certificate");
    assert!(matches!(
        cms.resolve_signature(
            certificate.signature_algorithm(),
            &DigestAlgorithm::Sha512,
            WorkingKey::standing(certificate.tbs().public_key()),
            Encoding::Der,
            &parent,
        ),
        Ok(Resolution::Unsupported)
    ));
}

/// Resolve the signature identifier of certificate fixture `name` for a signer
/// whose `digestAlgorithm` is `digest`.
fn resolve_own_signature(
    name: &str,
    digest: DigestAlgorithm,
) -> Result<Resolution<SignatureMode<X509SignatureAlgorithm>>, CmsProviderError> {
    let memory = Memory::new(Arc::new(MemoryAccount::new(1 << 20, 1 << 24)));
    let parser = Parser::der(memory);
    let policy = permissive();
    let provider = RustCryptoProvider;
    let cms = CmsProvider::new(&provider, &policy);
    let parent = parser.read(&[], 0).expect("reader");
    let bytes = fixture(&format!("{name}.der"));
    let certificate = Certificate::read(&parser, &bytes, 0).expect("certificate");
    cms.resolve_signature(
        certificate.signature_algorithm(),
        &digest,
        WorkingKey::standing(certificate.tbs().public_key()),
        Encoding::Der,
        &parent,
    )
}

#[test]
fn ed25519_requires_a_sha512_signer_digest() {
    // RFC 8419 3.1 and 3.2: the signature verifies over signedAttrs whatever
    // digestAlgorithm says, so only this check refuses another digest.
    assert!(matches!(
        resolve_own_signature("ed25519", DigestAlgorithm::Sha256),
        Ok(Resolution::Malformed)
    ));
    assert!(matches!(
        resolve_own_signature("ed25519", DigestAlgorithm::Sha512),
        Ok(Resolution::Supported(SignatureMode::Raw(
            X509SignatureAlgorithm::Ed25519
        )))
    ));
}

#[test]
fn ed448_refuses_every_digest_it_could_resolve() {
    // RFC 8419 3.1 and 3.2 require SHAKE256, which is no digest identity here.
    for digest in [DigestAlgorithm::Sha256, DigestAlgorithm::Sha512] {
        assert!(matches!(
            resolve_own_signature("ed448", digest),
            Ok(Resolution::Malformed)
        ));
    }
}

#[test]
fn rsa_pss_must_name_the_signer_digest() {
    // RFC 4056 section 3: the hash of signedAttrs and hashAlgorithm of the
    // RSASSA-PSS parameters MUST be the same.
    assert!(matches!(
        resolve_own_signature("rsa-pss-signed", DigestAlgorithm::Sha384),
        Ok(Resolution::Malformed)
    ));
    assert!(matches!(
        resolve_own_signature("rsa-pss-signed", DigestAlgorithm::Sha256),
        Ok(Resolution::Supported(SignatureMode::Raw(
            X509SignatureAlgorithm::RsaPss { .. }
        )))
    ));
}

#[test]
fn one_provider_charges_every_signer_to_one_certificate_account() {
    // max_x509_work is cumulative for a processing session: with the smallest
    // allowance one signer's key check fits, a second one through the same
    // provider is refused instead of receiving a fresh allowance.
    let memory = Memory::new(Arc::new(MemoryAccount::new(1 << 20, 1 << 24)));
    let parser = Parser::der(memory);
    let provider = RustCryptoProvider;
    let parent = parser.read(&[], 0).expect("reader");
    let bytes = fixture("rsa.der");
    let certificate = Certificate::read(&parser, &bytes, 0).expect("certificate");
    let key = certificate.tbs().public_key();
    let smallest = (1..=4096)
        .find(|&work| {
            let mut policy = permissive();
            policy.resources.max_x509_work = work;
            CmsProvider::new(&provider, &policy)
                .resolve_signature(
                    certificate.signature_algorithm(),
                    &DigestAlgorithm::Sha256,
                    WorkingKey::standing(key),
                    Encoding::Der,
                    &parent,
                )
                .is_ok()
        })
        .expect("an allowance that fits one key check");
    let mut policy = permissive();
    policy.resources.max_x509_work = smallest;
    let cms = CmsProvider::new(&provider, &policy);
    let resolve = || {
        cms.resolve_signature(
            certificate.signature_algorithm(),
            &DigestAlgorithm::Sha256,
            WorkingKey::standing(key),
            Encoding::Der,
            &parent,
        )
    };
    assert!(resolve().is_ok());
    assert!(resolve().is_err());
}

#[test]
fn ecdsa_must_name_the_signer_digest_and_rsa_encryption_takes_it() {
    // RFC 5753 §2.1.1: ecdsa-with-SHA256 under a SHA-384 digestAlgorithm is
    // malformed. RFC 3370 §3.2: rsaEncryption (NULL parameters) signs with
    // whatever digest digestAlgorithm names.
    let memory = Memory::new(Arc::new(MemoryAccount::new(1 << 20, 1 << 24)));
    let parser = Parser::der(memory);
    let policy = permissive();
    let provider = RustCryptoProvider;
    let cms = CmsProvider::new(&provider, &policy);
    let parent = parser.read(&[], 0).expect("reader");

    let ecdsa_bytes = fixture("ecdsa-p256.der");
    let ecdsa = Certificate::read(&parser, &ecdsa_bytes, 0).expect("certificate");
    let key = WorkingKey::standing(ecdsa.tbs().public_key());
    let resolve = |digest| {
        cms.resolve_signature(
            ecdsa.signature_algorithm(),
            &digest,
            key,
            Encoding::Der,
            &parent,
        )
    };
    assert!(matches!(
        resolve(DigestAlgorithm::Sha384),
        Ok(Resolution::Malformed)
    ));
    assert!(matches!(
        resolve(DigestAlgorithm::Sha256),
        Ok(Resolution::Supported(SignatureMode::Raw(
            X509SignatureAlgorithm::Ecdsa(DigestAlgorithm::Sha256)
        )))
    ));

    let rsa_bytes = fixture("rsa.der");
    let rsa = Certificate::read(&parser, &rsa_bytes, 0).expect("certificate");
    let rsa_key = rsa.tbs().public_key();
    assert!(matches!(
        cms.resolve_signature(
            rsa_key.algorithm(),
            &DigestAlgorithm::Sha384,
            WorkingKey::standing(rsa_key),
            Encoding::Der,
            &parent,
        ),
        Ok(Resolution::Supported(SignatureMode::Raw(
            X509SignatureAlgorithm::RsaPkcs1v15(DigestAlgorithm::Sha384)
        )))
    ));
}

#[test]
fn a_weak_rsa_signer_key_is_a_policy_violation() {
    // The TSA key is 2048-bit RSA; a 3072-bit minimum refuses it before the
    // signature is computed.
    let mut policy = permissive();
    policy.key_trust.rsa_keys.minimum_modulus_bits = 3072;
    let refusal = check(
        "rsa",
        &fixture("rsa.tst"),
        &fixture("payload.txt"),
        &policy,
        generous(),
    )
    .expect_err("weak key");
    assert!(refusal.is_policy(), "{refusal:?}");
}
